s up with glowing firm skin.","Peel off in the morning for glass skin without stickiness.","Perfect for fall dryness and loss of firmness."],"image":"https://m.media-amazon.com/images/I/61occWCJN-L._SL1500_.jpg","images":[],"url":"https://www.amazon.com/dp/B0BRMYHMS5?tag=beautynest202-20","store":"Amazon","bestseller":false,"price":null,"sale_price":null,"rating":null,"review_count":null,"added_date":null,"affiliate_links":{},"related_products":[],"sort_order":49},{"id":"haruharu-wonder-rose-pdrn-soothing-serum-with-az","brand":"haruharu wonder","name":"Rose PDRN Soothing Serum with Azelaic Acid 30ml","full_name":"Haruharu Wonder Rose PDRN Soothing Serum with Azelaic Acid 30ml","categories":["serums"],"short":"10% azelaic acid serum to soothe redness and even tone.","description":"10% azelaic acid with hyaluronic acid to soothe redness and help even the look of skin tone. Lightweight serum for sensitive skin.","features":["Soothing Korean PDRN serum for red, sensitive everyday skin.","Haruharu Wonder Rose PDRN Soothing Serum with Rose PDRN, Azelaic Acid and Bulgarian Rose calms redness, refines texture and evens tone without irritation.","Fragrance-free and vegan, perfect for reactive fall skin and blemish marks.","Apply after toner morning and night."],"image":"https://m.media-amazon.com/images/I/61PODyJiWUL._SL1500_.jpg","images":[],"url":"https://www.amazon.com/dp/B0FXX2JZLS?tag=beautynest202-20","store":"Amazon","bestseller":false,"price":null,"sale_price":null,"rating":null,"review_count":null,"added_date":null,"affiliate_links":{},"related_products":[],"sort_order":50}]$frostdew$::jsonb) as x(
    id text,
    brand text,
    name text,
    full_name text,
    categories text[],
    short text,
    description text,
    features text[],
    image text,
    images text[],
    url text,
    store text,
    bestseller boolean,
    sort_order integer,
    price text,
    sale_price text,
    rating numeric,
    review_count integer,
    added_date date,
    affiliate_links jsonb,
    related_products text[]
  )
)
insert into public.products (
  id, brand, name, full_name, categories, short, description, features,
  image, images, url, store, bestseller, sort_order, price, sale_price,
  rating, review_count, added_date, affiliate_links, related_products
)
select
  id, brand, name, full_name, categories, short, description, features,
  image, images, url, store, bestseller, sort_order, price, sale_price,
  rating, review_count, added_date,
  coalesce(affiliate_links, '{}'::jsonb),
  coalesce(related_products, '{}'::text[])
from seed
on conflict (id) do update set
  brand            = excluded.brand,
  name             = excluded.name,
  full_name        = excluded.full_name,
  categories       = excluded.categories,
  short            = excluded.short,
  description      = excluded.description,
  features         = excluded.features,
  image            = excluded.image,
  images           = excluded.images,
  url              = excluded.url,
  store            = excluded.store,
  bestseller       = excluded.bestseller,
  sort_order       = excluded.sort_order,
  price            = excluded.price,
  sale_price       = excluded.sale_price,
  rating           = excluded.rating,
  review_count     = excluded.review_count,
  added_date       = excluded.added_date,
  affiliate_links  = excluded.affiliate_links,
  related_products = excluded.related_products;

-- ---------------------------------------------------------------------------
-- Site settings + 1 partner link(s), written as one unit.
-- ---------------------------------------------------------------------------

select public.save_site_settings(
  $frostdew${"instagram":"","tiktok":"","pinterest":"https://www.pinterest.com/beautynest_skincare/","youtube":"","x":"","threads":""}$frostdew$::jsonb,
  $frostdew${"hero":{"eyebrow":"K-Beauty Skincare","headline":"FROSTDEW","subheadline":"Skincare for a Winter-Proof Glow","ctaLabel":"Shop the collection","ctaHref":"#shop","activeSeason":"winter","seasons":{"winter":{"type":"video","url":"/hero/hero-video.mp4","posterUrl":"/hero/hero-poster.jpg"},"springSummer":{"type":"image","url":"","posterUrl":""},"autumn":{"type":"image","url":"","posterUrl":""}}},"about":{"eyebrow":"Our Story","title":"About FrostDew","intro":"FrostDew is an independent edit of Korean skincare for cold air, indoor heating, and the long stretch of winter when skin asks for more."},"footer":{"tagline":"Skincare for a Winter-Proof Glow"},"contact":{"intro":"Questions about a product, a broken link, or something that needs correcting? Send a note and we will take a look.","responseTime":"We usually reply within 2 business days. Messages about a specific product are easiest to answer when you include the product name and the page you were on."}}$frostdew$::jsonb,
  $frostdew$[{"name":"BeautyNest Korea","url":"https://beautynestkorea.vercel.app/","new_tab":true,"position":0}]$frostdew$::jsonb
);

commit;

-- Verification -----------------------------------------------------------------
select count(*) as products, count(distinct brand_key || ' / ' || name_key) as unique_brand_names
from public.products;

select count(*) as partners from public.partners;

select id, updated_at from public.site_settings where id = 'default';
